import {fontFixture,fontLayoutFixture} from './font-test-fixtures.mjs';
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {EXPECTED_TAIHE} from './ui-oracles.mjs';
const here=path.dirname(new URL(import.meta.url).pathname);
const load = name => import(path.join(here,name));
const head='a'.repeat(40);
const env={GITHUB_SHA:head,GITHUB_RUN_ID:'123',GITHUB_RUN_ATTEMPT:'1',GITHUB_REPOSITORY:'watsonbkeel/forbidden-city-3d',GITHUB_REF:'refs/heads/test'};
const temp=t=>{const p=fs.mkdtempSync(path.join(os.tmpdir(),'ui-contract-'));t.after(()=>fs.rmSync(p,{recursive:true,force:true}));return p;};
test('identity requires complete trusted run fields',async()=>{const {readIdentity}=await load('common.mjs');assert.equal(readIdentity(env).eventSha,head);for(const key of Object.keys(env))assert.throws(()=>readIdentity({...env,[key]:''}));assert.throws(()=>readIdentity({...env,GITHUB_REPOSITORY:'other/repo'}));assert.throws(()=>readIdentity({...env,GITHUB_SHA:'unknown'}));});
test('input contract rejects traversal, symlinks, duplicates and modified bytes',async t=>{const {readInputs,sha256}=await load('common.mjs');const root=temp(t);fs.writeFileSync(path.join(root,'a'),'ok');fs.chmodSync(path.join(root,'a'),0o644);const entry={path:'a',mode:'100644',bytes:2,sha256:sha256(Buffer.from('ok'))};const manifest=path.join(root,'inputs.json');const put=files=>fs.writeFileSync(manifest,JSON.stringify({schema:1,files}));put([entry]);assert.equal(readInputs(root,manifest).files.length,1);for(const files of [[entry,entry],[{...entry,path:'../a'}],[{...entry,bytes:3}],[{...entry,sha256:'f'.repeat(64)}]]){put(files);assert.throws(()=>readInputs(root,manifest));}fs.symlinkSync('a',path.join(root,'link'));put([{...entry,path:'link'}]);assert.throws(()=>readInputs(root,manifest));});
test('collector preserves early failure receipt and rejects unknown files',async t=>{const {collectEvidence}=await load('collect-evidence.mjs');const root=temp(t),source=path.join(root,'receipts'),dest=path.join(root,'collected');fs.mkdirSync(source);fs.writeFileSync(path.join(source,'toolchain.json'),JSON.stringify({status:'failed',identity:{eventSha:head}}));fs.writeFileSync(path.join(source,'secret'),'not for upload');const result=collectEvidence({from:source,to:dest,expectedHead:head});assert.equal(result.complete,false);assert.equal(result.copied.length,1);assert.ok(result.rejected.some(x=>x.path==='secret'));assert.equal(fs.existsSync(path.join(dest,'secret')),false);assert.throws(()=>collectEvidence({from:source,to:dest,expectedHead:head}));});
test('collector does not follow ancestor symlink',async t=>{const {collectEvidence}=await load('collect-evidence.mjs');const root=temp(t),source=path.join(root,'receipts');fs.mkdirSync(source);fs.symlinkSync(root,path.join(source,'ui-components'));const result=collectEvidence({from:source,to:path.join(root,'collected'),expectedHead:head});assert.equal(result.complete,false);assert.ok(result.rejected.length);});
test('sandbox flags include equals variants',async()=>{const {validateBrowserArguments}=await load('verify-evidence.mjs');const binary='/opt/google/chrome/chrome';validateBrowserArguments([binary,'--headless']);for(const flag of ['--no-sandbox','--disable-setuid-sandbox','--disable-namespace-sandbox','--single-process','--no-zygote','--disable-seccomp-filter-sandbox','--disable-gpu-sandbox']){assert.throws(()=>validateBrowserArguments([binary,flag]));assert.throws(()=>validateBrowserArguments([binary,flag+'=false']));}assert.throws(()=>validateBrowserArguments(['/tmp/chrome']));});
test('version parsing rejects unavailable malformed and inconsistent stable packages',async()=>{const {parseChrome,parseRequiredVersion}=await load('preflight.mjs');assert.equal(parseRequiredVersion('v24.22.1',/^v(\d+\.\d+\.\d+)$/),'24.22.1');for(const value of ['', 'unknown','24'])assert.throws(()=>parseRequiredVersion(value,/^v(\d+\.\d+\.\d+)$/));assert.equal(parseChrome('Google Chrome 156.0.8078.47','google-chrome-stable\t156.0.8078.47-1\tinstall ok installed').version,'156.0.8078.47');assert.throws(()=>parseChrome('Google Chrome 156.0.8078.47','google-chrome-stable\t155.0.0.0-1\tinstall ok installed'));});
test('preflight records invalid identity failure and refuses output reuse without executing tools',async t=>{const {preflight}=await load('preflight.mjs');const root=temp(t),repo=path.join(root,'repo'),workRoot=path.join(root,'bui-123-1'),badEnv={...env,GITHUB_SHA:'invalid',RUNNER_TEMP:root,EVIDENCE_DIR:path.join(root,'main-evidence')};fs.mkdirSync(repo);const r=preflight({repo,workRoot,inputsPath:path.join(repo,'inputs'),env:badEnv});assert.equal(r.status,'failed');assert.equal(r.commands.length,0);assert.equal(JSON.parse(fs.readFileSync(path.join(workRoot,'receipts/toolchain.json'))).status,'failed');assert.throws(()=>preflight({repo,workRoot,inputsPath:'unused',env:badEnv}));});
test('verifier rejects unknown evidence entries',async t=>{const {validateEvidence}=await load('verify-evidence.mjs');const root=temp(t);await fixture(root);fs.writeFileSync(path.join(root,'unexpected'),'private');assert.throws(()=>validateEvidence(root,head,env),/Unknown/);});
async function fixture(root){const {EXPECTED_E46}=await load('ui-oracles.mjs');const {sha256,LOCK_SHA256,readIdentity}=await load('common.mjs');const {deflateSync}=await import('node:zlib');const identity=readIdentity(env);const memory=memoryFixture(identity);const hash='b'.repeat(64);const put=(name,value)=>{const p=path.join(root,name);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,typeof value==='string'||Buffer.isBuffer(value)?value:JSON.stringify(value));};const tool={schema:1,status:'passed',identity,inputsSHA256:hash,lockSHA256:LOCK_SHA256,toolchain:{imageOS:'ubuntu24',imageVersion:'20261102.1.0',node:'24.22.1',npm:'11.9.0',playwright:'1.64.0',playwrightCore:'1.64.0',vite:'5.4.21',python:'3.12.3',chrome:{path:'/opt/google/chrome/chrome',realpath:'/opt/google/chrome/chrome',version:'156.0.8078.47',packageVersion:'156.0.8078.47-1',sha256:hash}}};const fonts=fontFixture(identity);tool.toolchain.fonts=fonts.summary;put('fonts.json',fonts.receipt);put('toolchain.json',tool);const toolchainSHA256=sha256(fs.readFileSync(path.join(root,'toolchain.json')));const source={head,tree:'c'.repeat(40),status:'',files:[{path:'src/a.js',sha256:hash}],indexSHA256:hash,identity,inputsSHA256:hash,toolchainSHA256};put('ui-components/source-before.json',source);put('ui-components/monitor.json',{identity,memory:memory.monitor,processRoles:null,rootLaunched:true,durationSeconds:.3,rssPollingThresholdBytes:2048*1024**2,peakTreeRSSBytes:1000*1024**2,passed:true,rootReaped:true,sourceUnchanged:true,logComplete:true,returncode:0,signals:[],stopReason:null,identityConflicts:[],remainingOwnedProcesses:[],unattributedSessionProcesses:[],sourceAfter:source});put('monitor-contract.json',{schema:1,identity,passed:true,tests:42,failures:0,errors:0,skipped:0});put('ui-summary.json',{identity,passed:true});put('ui-components/full.log','synthetic complete log\n');put('ui-components/exit.txt','0\n');const layouts=[[1280,900],[390,844]].map(([width,height],index)=>({...layoutFixture(index),e46:e46Fixture(width,height,EXPECTED_E46),fontEvidence:fontLayoutFixture(width,height),width,height,errors:[],settings:{overflow:0,focus:'settings-language',quality:'high',sound:true,missing:[],untranslated:[]},sourceLimits:['zh-CN','en'].map(lang=>({...officialNameFields(lang),lang,passed:true,selected:'taihe',headings:['Another heading',...EXPECTED_TAIHE[lang].headings],notes:[...EXPECTED_TAIHE[lang].notes],links:EXPECTED_TAIHE.links.map(link=>({...link,text:'Source label'}))}))}));const stickySourceObservations=stickyRowsForLayouts(layouts);const sourceLimitObservations=layouts.flatMap((layout,index)=>layout.sourceLimits.map(({lang,passed,...view},n)=>({ordinal:index*2+n+1,width:layout.width,height:layout.height,locale:lang,selected:view.selected,view})));put('ui-components/evidence/RESULT.json',{stickySourceObservations,sourceLimitObservations,memoryPhases:phaseFixture(),uiSteps:stepFixture(),memoryAdmission:memory.receipt,identity,toolchainSHA256,browserVersion:tool.toolchain.chrome.version,browserArguments:[['/opt/google/chrome/chrome','--headless']],browserProcesses:[{pid:123,executable:'/opt/google/chrome/chrome',args:['/opt/google/chrome/chrome','--headless']}],pass:true,toolchainRechecked:true,errors:[],layouts});const crc=bytes=>{let v=0xffffffff;for(const b of bytes){v^=b;for(let k=0;k<8;k++)v=(v>>>1)^((v&1)?0xedb88320:0);}return (v^0xffffffff)>>>0;};const chunk=(type,data)=>{const b=Buffer.alloc(12+data.length);b.writeUInt32BE(data.length);b.write(type,4);data.copy(b,8);b.writeUInt32BE(crc(b.subarray(4,8+data.length)),8+data.length);return b;};for(const {width,height} of layouts){const h=Buffer.alloc(13);h.writeUInt32BE(width);h.writeUInt32BE(height,4);h[8]=8;h[9]=6;const png=Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',h),chunk('IDAT',deflateSync(Buffer.alloc((width*4+1)*height))),chunk('IEND',Buffer.alloc(0))]);for(const kind of ['english-card','english-settings','chinese-card','e46-chinese-card','e46-english-card','chinese-map','english-map'])put(`ui-components/evidence/${width}-${kind}.png`,png);}return {put,source};}
test('synthetic complete receipt passes and evidence mutations fail closed',async t=>{const {validateEvidence}=await load('verify-evidence.mjs');const root=temp(t);const {put}=await fixture(root);assert.equal(validateEvidence(root,head,env).passed,true);const mutations=[['ui-components/evidence/RESULT.json',x=>x.layouts.pop()],['ui-components/evidence/RESULT.json',x=>x.layouts.push(x.layouts[0])],['ui-components/evidence/RESULT.json',x=>x.errors.push('console error')],['ui-components/evidence/RESULT.json',x=>x.layouts[0].settings.missing.push('key')],['ui-components/evidence/RESULT.json',x=>x.layouts[0].sourceLimits[1].passed=false],['ui-components/evidence/RESULT.json',x=>x.browserVersion='1.2.3.4'],['ui-components/evidence/RESULT.json',x=>x.identity.runAttempt='2'],['ui-components/monitor.json',x=>x.logComplete=false],['ui-components/monitor.json',x=>x.remainingOwnedProcesses.push({pid:123})],['ui-components/monitor.json',x=>x.sourceAfter.head='d'.repeat(40)],['monitor-contract.json',x=>x.skipped=1],['toolchain.json',x=>x.toolchain.node='unknown']];for(const [file,mutate] of mutations){const full=path.join(root,file),original=fs.readFileSync(full);const doc=JSON.parse(original);mutate(doc);put(file,doc);assert.throws(()=>validateEvidence(root,head,env),file);fs.writeFileSync(full,original);}const png=path.join(root,'ui-components/evidence/390-english-card.png'),original=fs.readFileSync(png);fs.writeFileSync(png,original.subarray(0,40));assert.throws(()=>validateEvidence(root,head,env));fs.unlinkSync(png);assert.throws(()=>validateEvidence(root,head,env));});
test('collector retains malformed regular failure receipt and records rejection',async t=>{const {collectEvidence}=await load('collect-evidence.mjs');const root=temp(t),from=path.join(root,'receipts'),to=path.join(root,'out');fs.mkdirSync(from);fs.writeFileSync(path.join(from,'toolchain.json'),'{incomplete');const r=collectEvidence({from,to,expectedHead:head});assert.equal(r.complete,false);assert.equal(fs.readFileSync(path.join(to,'toolchain.json'),'utf8'),'{incomplete');assert.ok(r.rejected.some(x=>x.path==='toolchain.json'));});
test('empty required version command and nonzero command produce explicit unavailable receipt',async()=>{const {commandRunner}=await load('preflight.mjs');const commands=[],run=commandRunner(process.cwd(),commands);assert.throws(()=>run(process.execPath,['-e','']));assert.equal(commands[0].status,'unavailable');assert.throws(()=>run(process.execPath,['-e','process.stderr.write("synthetic failure");process.exit(3)']));assert.equal(commands[1].exit,3);assert.match(commands[1].stderr,/synthetic failure/);assert.equal(run(process.execPath,['-e','console.log("1.2.3")']),'1.2.3');});
