function stickyRowsForLayouts(layouts){
 const rect=(x,y,width,height)=>({x,y,width,height,top:y,right:x+width,bottom:y+height,left:x});
 return layouts.flatMap((layout,index)=>[layout.sourceBefore,...layout.sourceStates].map((state,n)=>{
  const sourceRect=rect(30,state.focusTop,200,20),panelRect=rect(20,100,layout.width-40,500);
  const box=(id,r)=>({id,tag:id==='place-info'?'SECTION':'DIV',connected:true,hidden:false,rect:r,borders:{top:'1px',right:'1px',bottom:'1px',left:'1px'},overflowX:'auto',overflowY:'auto',clientWidth:r.width-2,clientHeight:r.height-2,scrollTop:state.panelScroll,scrollHeight:state.panelMax+r.height-2,direction:'ltr',transform:'none'});
  state.stickySource={schema:1,active:{id:state.focusId,tag:'A',href:state.focusHref,connected:true},source:{id:state.focusId,tag:'A',href:state.focusHref,connected:true,hidden:false,active:true,inPanel:true,rect:sourceRect,clientRectCount:1,clientRects:[sourceRect]},panel:{...box('place-info',panelRect),inMinimap:true,scrollPaddingTop:'9px'},actions:{id:'place-actions',tag:'DIV',connected:true,hidden:false,inPanel:true,rect:rect(21,101,layout.width-42,9),position:'sticky',top:'0px'},minimap:{...box('minimap',rect(10,90,layout.width-20,520)),overflowX:'hidden',overflowY:'hidden'},counts:{source:1,panel:1,actions:1,minimap:1},viewport:{width:layout.width,height:layout.height,dpr:1},locale:state.lang,documentLang:state.lang,selected:state.selected,collectionErrors:[]};
  return {schema:1,ordinal:index*3+n+1,width:layout.width,height:layout.height,phase:n===0?'before':state.lang,state:structuredClone(state)};
 }));
}
