 const {validateEvidence}=await load('verify-evidence.mjs'),root=temp(t),{put}=await fixture(root),file='ui-components/evidence/RESULT.json',original=fs.readFileSync(path.join(root,file));const valid=validateEvidence(root,head,env);assert.equal(valid.passed,true);assert.equal(valid.stickySourceGeometry.length,6);assert.ok(valid.stickySourceGeometry.every(v=>v.passed&&v.clearances.length===2));
